with a as(select * from public.authors where open_library_id=any(array['OL1391085A','OL78910A','OL841112A']::text[])),w as(select * from public.works where open_library_id=any(array['OL5720022W','OL891786W','OL4321141W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9780316067928','9780385489386','9781400031702','9789022563915','9789044513202','9789060748107']::text[]) or open_library_edition_id=any(array['OL20962578M','OL10151159M','OL24933958M','OL26201158M','OL32362725M','OL24991771M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987155001 and 987155999),'editions',(select count(*) from public.editions where id between 987255001 and 987255999),'authors',(select count(*) from public.authors where id between 987355001 and 987355999))) as preflight;
